const context=$('Prepare Outreach Agent Input').item.json;
let result;
try {const raw=$json.output??$json; result=typeof raw==='string'?JSON.parse(raw):raw;} catch {return [{json:{...context,messages:[],outreach_valid:false,validation_errors:['Invalid agent JSON'],status:'failed_partial'}}];}
const errors=[]; const requiredDays=[0,3,7,12]; const forbidden=context.forbidden_claims||[];
if((result.messages||[]).length!==4) errors.push('Sequence must contain exactly four messages');
const messages=(result.messages||[]).map((m,index)=>{const body=String(m.body||''); if(Number(m.touch_number)!==index+1) errors.push(`Invalid touch number ${m.touch_number}`); if(Number(m.day_offset)!==requiredDays[index]) errors.push(`Invalid day offset for touch ${index+1}`); if(!body.includes('{{TRACKED_MEETING_LINK}}')) errors.push(`Touch ${index+1} lacks tracked CTA placeholder`); if(!/unsubscribe|opt out/i.test(body)) errors.push(`Touch ${index+1} lacks unsubscribe instruction`); for(const claim of forbidden) if((body+' '+m.subject).toLowerCase().includes(claim)) errors.push(`Forbidden claim in touch ${index+1}: ${claim}`); return {...m,touch_number:index+1,day_offset:requiredDays[index]};});
const knownSources=new Set((context.research?.findings||[]).flatMap(f=>f.source_keys||[])); for(const key of result.pain_source_keys||[]) if(!knownSources.has(key)) errors.push(`Unknown pain source key: ${key}`);
return [{json:{...context,...result,messages,outreach_valid:errors.length===0,validation_errors:[...new Set(errors)],status:errors.length?'failed_partial':'completed',intermediateSteps:$json.intermediateSteps||[]}}];

const message=$('Load Eligible Approved Messages').item.json;
if(!$json.url) throw new Error('Signed tracking link unavailable');
const escapeHtml=(value)=>String(value).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;').replace(/'/g,'&#039;');
const normalized=String(message.body||'').replace(/\\n/g,'\n').replace(/\r\n/g,'\n').trim();
const placeholder='{{TRACKED_MEETING_LINK}}';
if(!normalized.includes(placeholder)) throw new Error('Tracked meeting placeholder missing');
const body=normalized.replaceAll(placeholder,$json.url);
const safeUrl=escapeHtml($json.url);
const linked=escapeHtml(normalized).replaceAll(placeholder,`<a href="${safeUrl}" style="display:inline-block;padding:10px 16px;border-radius:6px;background:#1769e0;color:#ffffff;text-decoration:none;font-weight:600">Book a short conversation</a>`);
const paragraphs=linked.split(/\n{2,}/).map(part=>`<p style="margin:0 0 16px">${part.replace(/\n/g,'<br>')}</p>`).join('');
const body_html=`<div style="font-family:Arial,Helvetica,sans-serif;font-size:15px;line-height:1.6;color:#202124;max-width:620px">${paragraphs}</div>`;
return [{json:{...message,delivered_recipient:$vars.SAFE_TEST_EMAIL,body,body_html,safe_override_applied:true,tracking_link_signed:true}}];
